import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { normalizeText, normalizeTags, normalizeTag, validateId, object } from './validation.mjs';

export function openStore(path) {
  mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA foreign_keys = ON;
    PRAGMA busy_timeout = 5000;
    CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY,text TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS tags(name TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS note_tags(note_id INTEGER REFERENCES notes(id) ON DELETE CASCADE,tag TEXT REFERENCES tags(name),PRIMARY KEY(note_id,tag));`);
  let depth = 0;
  function transaction(fn) {
    const name = `batch_${depth++}`;
    db.exec(`SAVEPOINT ${name}`);
    try {
      const result = fn();
      db.exec(`RELEASE ${name}`);
      return result;
    } catch (error) {
      db.exec(`ROLLBACK TO ${name}; RELEASE ${name}`);
      throw error;
    } finally { depth--; }
  }
  const getNote = id => {
    validateId(id);
    const row = db.prepare('SELECT * FROM notes WHERE id=?').get(id);
    if (!row) return null;
    return { id: Number(row.id), text: row.text, createdAt: row.created_at, updatedAt: row.updated_at,
      tags: db.prepare('SELECT tag FROM note_tags WHERE note_id=? ORDER BY tag').all(id).map(r => r.tag) };
  };
  function attach(id, tags) {
    for (const tag of tags) {
      db.prepare('INSERT OR IGNORE INTO tags VALUES(?)').run(tag);
      db.prepare('INSERT INTO note_tags VALUES(?,?)').run(id, tag);
    }
  }
  return {
    transaction,
    createNote(text, tags = []) {
      text = normalizeText(text); tags = normalizeTags(tags);
      return transaction(() => {
        const now = new Date().toISOString();
        const id = Number(db.prepare('INSERT INTO notes(text,created_at,updated_at) VALUES(?,?,?)').run(text, now, now).lastInsertRowid);
        attach(id, tags);
        return getNote(id);
      });
    },
    getNote,
    listNotes(options = {}) {
      const { q, tag, limit = 50, offset = 0 } = object(options);
      if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('limit must be an integer from 1 to 100');
      if (!Number.isSafeInteger(offset) || offset < 0) throw new Error('offset must be a nonnegative integer');
      if (q !== undefined && typeof q !== 'string') throw new Error('q must be a string');
      const clauses = [], params = [];
      if (q !== undefined) { clauses.push('instr(lower(text),lower(?)) > 0'); params.push(q); }
      if (tag !== undefined) {
        clauses.push('EXISTS (SELECT 1 FROM note_tags WHERE note_id=notes.id AND tag=?)');
        params.push(normalizeTag(tag));
      }
      return db.prepare(`SELECT id FROM notes ${clauses.length ? 'WHERE ' + clauses.join(' AND ') : ''} ORDER BY id DESC LIMIT ? OFFSET ?`)
        .all(...params, limit, offset).map(r => getNote(Number(r.id)));
    },
    updateNote(id, patch) {
      validateId(id); object(patch);
      const text = Object.hasOwn(patch, 'text') ? normalizeText(patch.text) : undefined;
      const tags = Object.hasOwn(patch, 'tags') ? normalizeTags(patch.tags) : undefined;
      return transaction(() => {
        const old = getNote(id);
        if (!old) return null;
        const now = new Date(Math.max(Date.now(), Date.parse(old.updatedAt) + 1)).toISOString();
        db.prepare('UPDATE notes SET text=?,updated_at=? WHERE id=?').run(text ?? old.text, now, id);
        if (tags !== undefined) { db.prepare('DELETE FROM note_tags WHERE note_id=?').run(id); attach(id, tags); }
        return getNote(id);
      });
    },
    deleteNote(id) { validateId(id); return db.prepare('DELETE FROM notes WHERE id=?').run(id).changes > 0; },
    listTags() {
      return db.prepare('SELECT tag AS name,COUNT(*) AS count FROM note_tags GROUP BY tag ORDER BY tag').all()
        .map(r => ({ name: r.name, count: Number(r.count) }));
    },
    close() { db.close(); }
  };
}

import { normalizeText, normalizeTags, object } from './validation.mjs';

// Validate every field before the first write, then commit the batch together.
export function importNotes(store, records) {
  if (!Array.isArray(records)) throw new Error('notes must be an array');
  const prepared = records.map(record => {
    object(record);
    return { text: normalizeText(record.text), tags: normalizeTags(record.tags) };
  });
  const create = () => prepared.map(record => store.createNote(record.text, record.tags));
  return typeof store.transaction === 'function' ? store.transaction(create) : create();
}

export function allNotes(store) {
  const notes = [];
  for (let offset = 0; ; offset += 100) {
    const page = store.listNotes({ limit: 100, offset });
    notes.push(...page);
    if (page.length < 100) return notes;
  }
}

export function exportNotes(store) {
  return { version: 1, notes: allNotes(store).reverse().map(({ text, tags }) => ({ text, tags })) };
}

import { createInterface } from 'node:readline';
import { parseArgs } from 'node:util';
